"""tools_core.py  --  the tools that sit behind your Gateway.   >>> YOU DO NOT EDIT THIS FILE <<<

The SAME code runs in two places:
  - here, for the 'Practice gateway' (no AWS needed)
  - inside the AWS Lambda function `askit-get-ticket` (the trainer deployed it) that your real Gateway calls
It has no MCP code in it at all. A Lambda is a plain function: it takes the inputs, returns an answer.
The Gateway is what turns it into an MCP tool.

Day 12 change: make(data, strict=False).
  strict=False  (Day 11 behaviour)  'emp-1001', ' EMP-1001' and 'EMP-1001 ' are all accepted: the tool tidies the id itself.
  strict=True   (hardened)          only the exact form EMP-1001 / TKT-0004 is accepted. Anything else is refused by the TOOL.
Lab 16B tab 5 shows why this matters when a policy rule compares text.
"""
import re

import rag_tool

TOOLS = {   # name -> what the model is told (also in tool_schema.json, which you paste into the console)
    "get_ticket": "Look up one helpdesk ticket by its id, e.g. TKT-0004. Returns subject, priority, status and the employee id.",
    "get_user": "Look up one employee by id, e.g. EMP-1001. Returns name, department, location and whether the person is a VIP.",
    "reset_password": "Reset an employee's password. This CHANGES data. (Mock: nothing is really reset.)",
    "search_kb": "Search the helpdesk knowledge base (how-to articles: password, VPN, laptop, MFA, SLA ...). Returns the best matching articles with their ids.",
}

TICKET_FORM = re.compile(r"TKT-\d{4}")
USER_FORM = re.compile(r"EMP-\d{4}")


def make(data, strict=False, embed=None):
    """data = {"tickets": [...], "users": [...], "kb": [...]}  ->  {tool name: function(**inputs)}
    embed = None: search_kb matches words (Practice).  embed = a function: it matches meaning (the Lambda passes Titan Embeddings)."""
    tickets = {t["ticket_id"].lower(): t for t in data["tickets"]}
    users = {u["user_id"].lower(): u for u in data["users"]}

    def bad_id(kind, value, form, example):
        if strict and not form.fullmatch(str(value)):
            return {"error": f"Invalid {kind} id {str(value)!r}. Use exactly the form {example} (capital letters, no spaces)."}
        return None

    def get_ticket(ticket_id=""):
        err = bad_id("ticket", ticket_id, TICKET_FORM, "TKT-0004")
        if err:
            return err
        t = tickets.get(str(ticket_id).strip().lower())
        if not t:
            return {"error": f"Ticket {ticket_id} not found."}
        return {k: t[k] for k in ("ticket_id", "user_id", "subject", "category", "priority", "status")}

    def get_user(user_id=""):
        err = bad_id("employee", user_id, USER_FORM, "EMP-1001")
        if err:
            return err
        u = users.get(str(user_id).strip().lower())
        if not u:
            return {"error": f"User {user_id} not found."}
        return {"user_id": u["user_id"], "name": u["name"], "department": u["department"], "location": u["location"], "vip": u["vip"]}

    def reset_password(user_id=""):
        err = bad_id("employee", user_id, USER_FORM, "EMP-1001")
        if err:
            return err
        u = users.get(str(user_id).strip().lower())
        if not u:
            return {"error": f"User {user_id} not found."}
        return {"ok": True, "message": f"A temporary password was sent to the registered mobile of {u['name']}."}

    funcs = {"get_ticket": get_ticket, "get_user": get_user, "reset_password": reset_password}
    if data.get("kb"):
        funcs["search_kb"] = rag_tool.make_search(data["kb"], embed)
    return funcs
